<script lang="ts">
 import { calculateWeld } from './lib/welding.mjs';
 import { estimateCnc, estimateCut, estimateBending } from './lib/estimate.mjs';
 import { massFromVolume } from './lib/geometry.mjs';
 let tab=$state('Frezowanie');
 let volumeMm3=$state(1000000),densityKgM3=$state(7850),partQuantity=$state(1);
 let partMass=$derived.by(()=>{try{return massFromVolume(volumeMm3,densityKgM3)}catch{return null}});
 let removedCm3=$state(100), removalCm3Min=$state(10), cncSetup=$state(20), contourMm=$state(3000), cutFeed=$state(1500), pierces=$state(10), bends=$state(4), bendSeconds=$state(30), rate=$state(388);
 let cnc=$derived.by(()=>{try{return estimateCnc({removedCm3,removalCm3Min,setupMin:cncSetup,ratePerHour:rate})}catch{return null}});
 let cutting=$derived.by(()=>{try{return estimateCut({contourMm,feedMmMin:cutFeed,pierces,ratePerHour:rate})}catch{return null}});
 let bending=$derived.by(()=>{try{return estimateBending({bends,secondsPerBend:bendSeconds,ratePerHour:rate})}catch{return null}}); let lengthM=$state(8), throatMm=$state(4), depositionKgH=$state(2), arcPercent=$state(35), setupMin=$state(20);
 let result=$derived.by(()=>{try{return calculateWeld({lengthM,throatMm,depositionKgH,arcFactor:arcPercent/100,setupMin})}catch{return null}});
 const tabs=['Nowa wycena','Masa i geometria','Frezowanie','Cięcie','Gięcie','Spawanie','Wyniki','Podgląd 3D','Ustawienia'];
 const fmt=(n:number)=>n.toLocaleString('pl-PL',{maximumFractionDigits:2,minimumFractionDigits:2});
</script>
<svelte:head><meta name="theme-color" content="#11151c"/></svelte:head>
<div class="app"><aside><div class="brand"><span class="mark">DS</span><div><b>DS Estimate</b><small>Desktop · 2.0 alpha</small></div></div><nav>{#each tabs as t}<button class:active={tab===t} onclick={()=>tab=t}>{t}</button>{/each}</nav><div class="bottom">Svelte 5 · Tauri 2<br/>Offline</div></aside><main><header><div><small>PROJEKT / WYCENA</small><h1>{tab}</h1></div><span class="status">● Prototyp</span></header>{#if tab==='Masa i geometria'}<section class="panel"><h2>Masa części z objętości B-Rep</h2><p>Przeliczenie masy na podstawie objętości podanej przez silnik CAD. Automatyczny import STEP i weryfikacja identyczności brył są w przygotowaniu.</p><div class="fields"><label>Objętość [mm³]<input type="number" min="0" bind:value={volumeMm3}/></label><label>Gęstość [kg/m³]<input type="number" min="0" bind:value={densityKgM3}/></label><label>Ilość sztuk<input type="number" min="1" step="1" bind:value={partQuantity}/></label></div></section><div class="stats"><article><small>Masa jednostkowa</small><strong>{partMass!==null?fmt(partMass):'—'} <em>kg</em></strong></article><article><small>Masa całkowita</small><strong>{partMass!==null&&Number.isInteger(partQuantity)&&partQuantity>=1?fmt(partMass*partQuantity):'—'} <em>kg</em></strong></article></div>{:else if tab==='Frezowanie'}<section class="panel"><h2>Szacowanie frezowania CNC</h2><p>Model objętościowy. Parametry wprowadza technolog; import STEP i CAM nie są jeszcze podłączone.</p><div class="fields"><label>Objętość do usunięcia [cm³]<input type="number" min="0" bind:value={removedCm3}/></label><label>Wydajność usuwania [cm³/min]<input type="number" min="0.01" bind:value={removalCm3Min}/></label><label>Przygotowanie [min]<input type="number" min="0" bind:value={cncSetup}/></label><label>Stawka [zł/h]<input type="number" min="0" bind:value={rate}/></label></div></section><div class="stats"><article><small>Czas skrawania</small><strong>{cnc?fmt(cnc.millingMin):'—'} <em>min</em></strong></article><article><small>Czas całkowity</small><strong>{cnc?fmt(cnc.totalMin):'—'} <em>min</em></strong></article><article><small>Koszt</small><strong>{cnc?fmt(cnc.cost):'—'} <em>zł</em></strong></article></div>{:else if tab==='Cięcie'}<section class="panel"><h2>Szacowanie cięcia</h2><p>Długość konturu, przebicia i czas przygotowania; nesting i DXF jeszcze niepodłączone.</p><div class="fields"><label>Długość konturu [mm]<input type="number" min="0" bind:value={contourMm}/></label><label>Prędkość cięcia [mm/min]<input type="number" min="0.01" bind:value={cutFeed}/></label><label>Liczba przebić<input type="number" min="0" bind:value={pierces}/></label><label>Stawka [zł/h]<input type="number" min="0" bind:value={rate}/></label></div></section><div class="stats"><article><small>Czas cięcia i przygotowania</small><strong>{cutting?fmt(cutting.totalMin):'—'} <em>min</em></strong></article><article><small>Koszt</small><strong>{cutting?fmt(cutting.cost):'—'} <em>zł</em></strong></article></div>{:else if tab==='Gięcie'}<section class="panel"><h2>Szacowanie gięcia</h2><p>Czas operacyjny i przygotowanie; rozwijanie blach nie jest jeszcze podłączone.</p><div class="fields"><label>Liczba gięć<input type="number" min="0" bind:value={bends}/></label><label>Czas jednego gięcia [s]<input type="number" min="0" bind:value={bendSeconds}/></label><label>Stawka [zł/h]<input type="number" min="0" bind:value={rate}/></label></div></section><div class="stats"><article><small>Czas całkowity</small><strong>{bending?fmt(bending.totalMin):'—'} <em>min</em></strong></article><article><small>Koszt</small><strong>{bending?fmt(bending.cost):'—'} <em>zł</em></strong></article></div>{:else if tab==='Spawanie'}<section class="panel"><h2>Kalkulator czasu spawania</h2><p>Spoiny pachwinowe o równych ramionach. Wyniki szacunkowe.</p><div class="fields"><label>Długość spoin [m]<input type="number" min="0" bind:value={lengthM}/></label><label>Gardziel a [mm]<input type="number" min="0" bind:value={throatMm}/></label><label>Wydajność stapiania [kg/h]<input type="number" min="0.01" step="0.1" bind:value={depositionKgH}/></label><label>Udział czasu łuku [%]<input type="number" min="1" max="100" bind:value={arcPercent}/></label><label>Przygotowanie [min]<input type="number" min="0" bind:value={setupMin}/></label></div></section><div class="stats"><article><small>Masa spoiny</small><strong>{result?fmt(result.massKg):'—'} <em>kg</em></strong></article><article><small>Czas łuku</small><strong>{result?fmt(result.arcMinutes):'—'} <em>min</em></strong></article><article><small>Czas całkowity</small><strong>{result?fmt(result.totalMinutes/60):'—'} <em>h</em></strong></article></div>{:else}<section class="panel empty"><h2>{tab}</h2><p>Moduł w przygotowaniu. Analiza STEP/PDF/DXF/DWG i wykrywanie spoin nie są jeszcze zaimplementowane.</p></section>{/if}<footer>Wyniki wymagają weryfikacji technologicznej.</footer></main></div>
