ont-size:27px;overflow-wrap:anywhere}.stats em{font-size:14px;font-style:normal;color:#9aa9ba}footer{margin-top:30px;color:#7d8b9e;font-size:12px}.empty{min-height:200px}@media(max-width:800px){aside{width:170px}main{padding:20px}.stats{grid-template-columns:1fr}.fields{grid-template-columns:1fr}}@media(max-width:550px){.app{display:block}aside{width:auto;padding:12px}.brand{padding:5px 10px 10px}nav{display:flex;overflow:auto}.bottom{display:none}nav button{white-space:nowrap;padding:10px}header{align-items:flex-start;flex-direction:column}.panel{padding:18px}}
</style>